  removalLead:
    "Las solicitudes se revisan manualmente. Antes de retirar información, confirmamos la petición mediante un contacto institucional publicado en la fuente oficial. Enviar este formulario no elimina ninguna ficha.",
  privacyTitle: "Privacidad",
  privacyLead:
    "Este sitio no utiliza analítica, cookies publicitarias ni cuentas de usuario. La búsqueda se ejecuta en tu navegador. El proveedor de alojamiento puede tratar registros técnicos de acceso. Al escribirnos compartes la información que decidas enviar.",
  historySlug: "historia",
  historyNav: "Historia del proyecto 2014-2016",
  historySection: "El proyecto de 2014-2016",
  historyLead:
    "Este dominio alojó el proyecto European Farm Succession entre 2016 y 2018. Aquel proyecto terminó; el sitio actual es independiente y no tiene relación con su consorcio.",
  historyMore: "Leer la historia completa del proyecto 2014-2016",
  historyTitle: "El proyecto European Farm Succession y este dominio",
  historyIntro:
    "Entre 2016 y 2018 este dominio alojó los resultados de otro proyecto europeo. Esta página documenta qué fue, qué produjo y qué relación tiene con el sitio actual.",
  historyObjectivesTitle: "Problema y objetivos",
  historyObjectivesLead:
    "El proyecto respondía al envejecimiento de la población agraria, a las explotaciones sin sucesor identificado y a las dificultades para incorporarse al campo desde fuera de una familia agraria. Los socios compartieron y adaptaron métodos para transmisiones familiares y extrafamiliares e intentaron situar el relevo generacional en la agenda política europea.",
  historyPartnersTitle: "Países y socios",
  historyPartnersLead:
    "Farm Succession in Europe fue un proyecto Erasmus+ (2014-2016), coordinado por FRCIVAM Bretagne junto con InterAFOCG en Francia, Terre-en-vue en Bélgica, NEL en Austria y Land & Co / Landgilde en los Países Bajos.",
  historyResultsTitle: "Resultados principales",
  historyResultsLead:
    "Los socios compartieron métodos para la transmisión familiar y extrafamiliar. Su principal resultado conservado es una guía de 52 páginas con un proceso de ocho fases y doce herramientas prácticas, presentada en la conferencia de Bruselas del 7 y 8 de noviembre de 2016.",
  historyDocumentsTitle: "Documentos originales y conservación",
  historyDocument: "Leer la guía original de 2016 (PDF, 3,9 MB)",
  historyPreservation:
    "Se ha recuperado la guía original y se conserva en la dirección que tenía, para que los enlaces que apuntan a ella desde fuera sigan funcionando. No se ha localizado copia de la nota conceptual ni de las diapositivas iniciales, así que aquí no se reconstruye su contenido.",
  historyCurrentTitle: "Relación con el sitio actual",
  historyCurrentLead:
    "El proyecto original terminó y el dominio caducó después. José Antonio Cano Trigueros lo registró de nuevo en 2026 para este inventario independiente y no comercial. El sitio actual no continúa ni representa al antiguo consorcio.",
  backAbout: "Volver a Sobre el proyecto",
  licenceTitle: "Licencia",
  licenceLead:
    "Nuestras descripciones originales y los derechos que podemos conceder sobre la selección y organización del directorio están disponibles bajo CC BY 4.0. Puedes compartirlas y adaptarlas, incluso comercialmente, con la atribución adecuada, un enlace a la licencia y una indicación de los cambios, sin sugerir respaldo. No imponemos restricciones adicionales a esos materiales licenciados.",
  licenceThirdParty:
    "Las citas, imágenes, documentos, bases de datos y demás materiales de terceros, incluidas las páginas enlazadas y la guía histórica, conservan sus derechos y condiciones. Hemos contactado con algunas organizaciones para solicitar permisos concretos; eso no significa que todas las fuentes hayan dado permiso o respalden el proyecto. Una autorización específica a FarmSuccession no se extiende automáticamente a quienes reutilicen el directorio. Consulta las condiciones originales y, si necesitas autorización, contacta directamente con el titular de los derechos o la organización responsable. FarmSuccession no puede conceder derechos ajenos.",
  licenceLawful:
    "Los enlaces habituales, las menciones, los hechos no protegidos y los usos ya permitidos por una licencia o por la ley aplicable no requieren siempre un permiso adicional. Este aviso no restringe esos usos ni exige atribución por el mero hecho de enlazar. El archivo LICENSE del repositorio distingue el código propio y las dependencias de terceros.",
