  privacyTitle: "Απόρρητο",
  privacyLead:
    "Ο ιστότοπος δεν χρησιμοποιεί εργαλεία ανάλυσης επισκεψιμότητας, διαφημιστικά cookies ή λογαριασμούς. Η αναζήτηση εκτελείται στο πρόγραμμα περιήγησης. Ο πάροχος φιλοξενίας ενδέχεται να επεξεργάζεται τεχνικά αρχεία καταγραφής πρόσβασης. Αν μας γράψεις, μας κοινοποιείς τις πληροφορίες που επιλέγεις να στείλεις.",
  historySlug: "istoriko",
  historyNav: "Ιστορικό του έργου 2014–2016",
