  historyLead:
    "Από το 2016 έως το 2018, αυτή η διαδικτυακή διεύθυνση φιλοξενούσε τα αποτελέσματα του ευρωπαϊκού έργου Farm Succession. Το έργο έχει ολοκληρωθεί. Ο σημερινός ιστότοπος είναι ανεξάρτητος από την τότε κοινοπραξία.",
  historyMore: "Διάβασε το πλήρες ιστορικό του έργου 2014–2016",
  historyTitle: "Το έργο Farm Succession και αυτή η διεύθυνση",
  historyIntro:
    "Από το 2016 έως το 2018, αυτή η διαδικτυακή διεύθυνση φιλοξενούσε τα αποτελέσματα ενός άλλου ευρωπαϊκού έργου. Η σελίδα παρουσιάζει το έργο, τα αποτελέσματά του και πώς συνδέεται η διεύθυνση με τον σημερινό ιστότοπο.",
  historyObjectivesTitle: "Το πρόβλημα και οι στόχοι",
  historyObjectivesLead:
    "Το έργο ασχολήθηκε με τη γήρανση του αγροτικού πληθυσμού, την έλλειψη διαδόχων και τις δυσκολίες όσων μπαίνουν στη γεωργία χωρίς να προέρχονται από αγροτική οικογένεια. Οι εταίροι προσάρμοσαν μεθόδους μεταβίβασης εντός και εκτός οικογένειας και επιδίωξαν να ενταχθεί η ανανέωση των γενεών στην ευρωπαϊκή ατζέντα.",
  historyPartnersTitle: "Χώρες και εταίροι",
  historyPartnersLead:
    "Το Farm Succession in Europe ήταν έργο Erasmus+ (2014–2016). Τον συντονισμό είχε η FRCIVAM Bretagne, με τη συμμετοχή της InterAFOCG στη Γαλλία, της Terre-en-vue στο Βέλγιο, της NEL στην Αυστρία και της Land & Co / Landgilde στις Κάτω Χώρες.",
  historyResultsTitle: "Κύρια αποτελέσματα",
  historyResultsLead:
    "Οι εταίροι αντάλλαξαν μεθόδους μεταβίβασης εντός και εκτός οικογένειας. Το κύριο παραδοτέο που σώζεται είναι ένας οδηγός 52 σελίδων με οκτώ στάδια και δώδεκα πρακτικά εργαλεία, ο οποίος παρουσιάστηκε στις Βρυξέλλες στις 7 και 8 Νοεμβρίου 2016.",
  historyDocumentsTitle: "Τα πρωτότυπα έγγραφα και η διατήρησή τους",
