  historyCurrentTitle: "Η σχέση με τον σημερινό ιστότοπο",
  historyCurrentLead:
    "Το αρχικό έργο ολοκληρώθηκε και αργότερα έληξε η κατοχύρωση του ονόματος χώρου. Ο José Antonio Cano Trigueros το κατοχύρωσε εκ νέου το 2026 για αυτόν τον ανεξάρτητο, μη εμπορικό κατάλογο. Ο σημερινός ιστότοπος δεν συνεχίζει το αρχικό έργο και δεν εκπροσωπεί την προηγούμενη κοινοπραξία.",
