  aboutIntro:
    "José Antonio Cano Trigueros független gyűjteménye. A gazdaságok indításához, átvételéhez vagy átadásához gyűjt össze termőfölddel, finanszírozással, képzéssel és szaktanácsadással kapcsolatos forrásokat. A kérelmeket és a szolgáltatásokat az adatlapokon megjelölt szervezetek kezelik.",
  overviewTitle: "Mi ez a projekt?",
